import hmac
import hashlib
import json
import time
import os
import secrets
from typing import Optional, Dict, Tuple

# Secure session management with HMAC-signed cookies
def _get_secret_key() -> bytes:
    key = os.environ.get('SESSION_SECRET', '')
    if not key or len(key) < 32:
        raise RuntimeError('SESSION_SECRET must be set and at least 32 characters')
    return key.encode()

SECRET_KEY = _get_secret_key()
SESSION_DURATION = 3600

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Constant-time comparison to prevent timing attacks."""
    return hmac.compare_digest(a, b)

def create_session(user_id: str, role: str, permissions: list) -> str:
    """Create a signed session token with user metadata."""
    # Validate inputs to prevent injection
    if not user_id or not isinstance(user_id, str):
        raise ValueError('Invalid user_id')
    if not user_id.isascii() or len(user_id) > 128:
        raise ValueError('user_id must be ASCII and <= 128 chars')
    if role not in ('admin', 'moderator', 'user', 'guest'):
        raise ValueError('Invalid role')
    if not isinstance(permissions, list) or not all(isinstance(p, str) and p.isascii() for p in permissions):
        raise ValueError('Invalid permissions')

    payload = {
        'uid': user_id,
        'role': role,
        'perms': permissions,
        'iat': int(time.time()),
        'exp': int(time.time()) + SESSION_DURATION
    }
    payload_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode()
    signature = hmac.new(SECRET_KEY, payload_bytes, hashlib.sha256).hexdigest()
    import base64
    token = base64.urlsafe_b64encode(payload_bytes).decode() + '.' + signature
    return token

def decode_token(token: str) -> Optional[Dict]:
    """Decode and verify a session token. Returns payload if valid."""
    import base64

    if not isinstance(token, str) or len(token) > 4096:
        return None

    parts = token.split('.')
    if len(parts) != 2:
        return None

    encoded_payload, provided_sig = parts[0], parts[1]

    # Validate signature format
    if len(provided_sig) != 64 or not all(c in '0123456789abcdef' for c in provided_sig):
        return None

    try:
        payload_bytes = base64.urlsafe_b64decode(encoded_payload + '==')
    except Exception:
        return None

    expected_sig = hmac.new(SECRET_KEY, payload_bytes, hashlib.sha256).hexdigest()

    if not constant_time_compare(expected_sig.encode(), provided_sig.encode()):
        return None

    try:
        payload = json.loads(payload_bytes)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return None

    # Validate payload structure
    if not isinstance(payload, dict):
        return None
    required_fields = {'uid', 'role', 'perms', 'iat', 'exp'}
    if not required_fields.issubset(payload.keys()):
        return None
    if not isinstance(payload['exp'], int) or not isinstance(payload['iat'], int):
        return None
    if not isinstance(payload['uid'], str) or not isinstance(payload['role'], str):
        return None
    if not isinstance(payload['perms'], list):
        return None
    # Reject empty/whitespace-only uid to match create_session guarantees and
    # prevent an empty-uid token from matching a policy with no defined owner.
    if not payload['uid'].strip():
        return None

    return payload

def validate_session(token: str) -> Optional[Dict]:
    """Validate session token and check expiry."""
    payload = decode_token(token)
    if payload is None:
        return None

    # Check expiry
    now = int(time.time())
    if now >= payload['exp']:
        return None

    # Check issued-at is not in the future (clock skew tolerance: 30s)
    if payload['iat'] > now + 30:
        return None

    return payload

# Permission-based access control
class AccessController:
    def __init__(self):
        self.role_hierarchy = {
            'admin': 100,
            'moderator': 50,
            'user': 10,
            'guest': 0
        }
        self._policy_cache: Dict[str, Tuple[Dict, float]] = {}
        self._cache_ttl = 300  # 5 minutes

    def get_effective_permissions(self, session: Dict) -> set:
        """Get effective permissions including role-inherited ones."""
        base_perms = set(session.get('perms', []))
        role = session.get('role', 'guest')

        # Role-based permission inheritance
        role_level = self.role_hierarchy.get(role, 0)
        if role_level >= 100:
            base_perms.update(['read', 'write', 'delete', 'admin'])
        elif role_level >= 50:
            base_perms.update(['read', 'write', 'moderate'])
        elif role_level >= 10:
            base_perms.update(['read', 'write'])
        else:
            base_perms.add('read')

        return base_perms

    def check_permission(self, token: str, required_perm: str) -> bool:
        """Check if a session token grants the required permission."""
        session = validate_session(token)
        if session is None:
            return False

        effective_perms = self.get_effective_permissions(session)
        return required_perm in effective_perms

    def check_role_level(self, token: str, min_role: str) -> bool:
        """Check if session has at least the specified role level."""
        session = validate_session(token)
        if session is None:
            return False

        user_level = self.role_hierarchy.get(session.get('role', 'guest'), 0)
        required_level = self.role_hierarchy.get(min_role, 0)
        return user_level >= required_level

    def get_cached_policy(self, resource_id: str) -> Optional[Dict]:
        """Get cached access policy for a resource."""
        if resource_id in self._policy_cache:
            policy, cached_at = self._policy_cache[resource_id]
            if time.time() - cached_at < self._cache_ttl:
                return policy
            else:
                del self._policy_cache[resource_id]
        return None

    def set_cached_policy(self, resource_id: str, policy: Dict):
        """Cache an access policy."""
        self._policy_cache[resource_id] = (policy, time.time())

    def evaluate_policy(self, token: str, resource_id: str, action: str) -> bool:
        """Evaluate access policy for a resource action."""
        session = validate_session(token)
        if session is None:
            return False

        policy = self.get_cached_policy(resource_id)
        if policy is None:
            # Default policy: owner can do anything, others need explicit permission
            policy = {'owner_only': True, 'allowed_actions': ['read']}

        user_role = session.get('role', 'guest')
        user_id = session.get('uid', '')

        # Admin bypass - admins can access everything
        if self.role_hierarchy.get(user_role, 0) >= 100:
            return True

        # Check if user is resource owner
        resource_owner = policy.get('owner', '')
        # Require a non-empty owner and non-empty user_id before granting
        # owner access, so a missing owner never matches an (empty) uid.
        if policy.get('owner_only') and resource_owner and user_id and user_id == resource_owner:
            return True

        # Check allowed actions for non-owners
        if action in policy.get('allowed_actions', []):
            return True

        return False


# Request handler with rate limiting
class RequestHandler:
    def __init__(self):
        self.ac = AccessController()
        self.rate_limits: Dict[str, list] = {}
        self.max_requests_per_minute = 60

    def _check_rate_limit(self, client_id: str) -> bool:
        """Returns True if request is allowed under rate limit."""
        now = time.time()
        if client_id not in self.rate_limits:
            self.rate_limits[client_id] = []

        # Remove old entries
        self.rate_limits[client_id] = [
            t for t in self.rate_limits[client_id] if now - t < 60
        ]

        if len(self.rate_limits[client_id]) >= self.max_requests_per_minute:
            return False

        self.rate_limits[client_id].append(now)
        return True

    def handle_request(self, client_id: str, token: str, resource: str, action: str) -> Dict:
        """Handle an incoming request with full auth chain."""
        # Rate limiting
        if not self._check_rate_limit(client_id):
            return {'status': 429, 'error': 'Rate limit exceeded'}

        # Token validation
        session = validate_session(token)
        if session is None:
            return {'status': 401, 'error': 'Invalid or expired session'}

        # Authorization
        if not self.ac.evaluate_policy(token, resource, action):
            return {'status': 403, 'error': 'Access denied'}

        return {'status': 200, 'data': f'Action {action} on {resource} successful'}

    def handle_admin_request(self, token: str, admin_action: str, target: str) -> Dict:
        """Handle admin-only requests."""
        session = validate_session(token)
        if session is None:
            return {'status': 401, 'error': 'Invalid or expired session'}

        # Verify admin role
        if not self.ac.check_role_level(token, 'admin'):
            return {'status': 403, 'error': 'Admin access required'}

        if admin_action == 'revoke_user':
            return {'status': 200, 'data': f'User {target} revoked'}
        elif admin_action == 'set_policy':
            return {'status': 200, 'data': f'Policy for {target} updated'}
        else:
            return {'status': 400, 'error': 'Unknown admin action'}


def upgrade_session(old_token: str, new_role: str, new_perms: list) -> Optional[str]:
    """Upgrade a session to a new role. Requires valid existing session.

    This is used during privilege escalation flows (e.g., after MFA verification).
    The new token inherits the original user_id but gets new role/permissions.
    """
    session = validate_session(old_token)
    if session is None:
        return None

    # Validate the new role is actually higher (prevent downgrades being used as upgrades)
    ac = AccessController()
    old_level = ac.role_hierarchy.get(session.get('role', 'guest'), 0)
    new_level = ac.role_hierarchy.get(new_role, 0)
    if new_level < old_level:
        return None

    # Create upgraded session preserving user identity
    return create_session(session['uid'], new_role, new_perms)


def merge_sessions(primary_token: str, secondary_token: str) -> Optional[str]:
    """Merge permissions from two valid sessions into one.

    Used when a user authenticates via multiple identity providers.
    Both sessions must belong to the same user_id.
    Takes the higher role and union of permissions.
    """
    primary = validate_session(primary_token)
    secondary = validate_session(secondary_token)

    if primary is None or secondary is None:
        return None

    # CRITICAL: Both sessions must belong to the same user
    if primary['uid'] != secondary['uid']:
        return None

    user_id = primary['uid']

    # Take the higher role
    ac = AccessController()
    primary_level = ac.role_hierarchy.get(primary.get('role', 'guest'), 0)
    secondary_level = ac.role_hierarchy.get(secondary.get('role', 'guest'), 0)

    if secondary_level > primary_level:
        merged_role = secondary['role']
    else:
        merged_role = primary['role']

    # Union of permissions
    merged_perms = list(set(primary.get('perms', [])) | set(secondary.get('perms', [])))

    return create_session(user_id, merged_role, merged_perms)


